PAIRS = [
    (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
    (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
    (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I'),
]


def to_roman(n):
    if not 1 <= n <= 3999:
        raise ValueError(f'n must be in 1..3999, got {n!r}')
    out = ''
    for value, sym in PAIRS:
        count, n = divmod(n, value)
        out += sym * count
    return out
